//! The build-script body every vendored grammar shares.
//!
//! Call it from `bindings/rust/build.rs`:
//!
//! ```no_run
//! fn main() {
//!     tree_sitter_build::compile();
//! }
//! ```
//!
//! Everything it needs it reads from the environment cargo sets for the *calling*
//! crate's build script, so there is nothing to pass and nothing to keep in sync.

use std::path::{Path, PathBuf};

/// The directory of the crate whose build script is running.
///
/// `std::env::var`, never `env!`: the latter would bake in this crate's own
/// directory at the time *this* crate was compiled, which is the same wrong
/// answer for all nine callers.
fn manifest_dir() -> PathBuf {
    PathBuf::from(std::env::var("CARGO_MANIFEST_DIR").expect("cargo sets CARGO_MANIFEST_DIR"))
}

/// The `tree_sitter/` headers every generated parser includes.
///
/// `tree-sitter generate` writes a private copy of `parser.h` -- and, for a
/// grammar with an external scanner, `alloc.h` and `array.h` -- into each
/// grammar's `src/tree_sitter/`. Nine vendored grammars meant nine identical
/// copies, so they live once in `vendor/tree-sitter-headers` instead. See the
/// README there, including what to do after regenerating a grammar.
fn shared_tree_sitter_headers(manifest: &Path) -> PathBuf {
    manifest
        .parent()
        .expect("a vendored grammar lives at vendor/<name>")
        .join("tree-sitter-headers")
}

/// Compile the calling crate's `src/parser.c`, and its `src/scanner.c` if it has
/// one, into a static library named after the crate.
///
/// # Panics
///
/// If cargo's environment is missing, or if targeting `wasm32-unknown-unknown`
/// without `tree-sitter-language`'s wasm sysroot variables.
pub fn compile() {
    let manifest = manifest_dir();
    let src_dir = manifest.join("src");
    let library_name = std::env::var("CARGO_PKG_NAME").expect("cargo sets CARGO_PKG_NAME");

    let mut c_config = cc::Build::new();
    // `src` first, so a grammar that keeps a `src/tree_sitter/` of its own
    // overrides the shared headers rather than colliding with them.
    c_config.std("c11").include(&src_dir);

    let shared_headers = shared_tree_sitter_headers(&manifest);
    c_config.include(&shared_headers);
    println!("cargo:rerun-if-changed={}", shared_headers.display());

    // `src/` is generated by tree-sitter-cli and vendored as it comes, and it does
    // not compile warning-free: scanners have `\`-continued `//` comments
    // (-Wcomment), wint_t/char comparisons (-Wsign-compare) and intentional switch
    // fall-throughs (-Wimplicit-fallthrough). Cargo hides build-script output for
    // registry dependencies, which is why the ~30 grammars that come from
    // crates.io are quiet and these -- path dependencies -- are not. Since we do
    // not maintain the generated source, silence `cc`'s -Wall/-Wextra rather than
    // patch code we would have to re-patch on every regeneration.
    c_config
        .warnings(false)
        .flag_if_supported("-Wno-comment")
        .flag_if_supported("-Wno-sign-compare")
        .flag_if_supported("-Wno-implicit-fallthrough")
        .flag_if_supported("-Wno-unused-parameter")
        .flag_if_supported("-Wno-unused-but-set-variable")
        .flag_if_supported("-Wno-trigraphs");

    #[cfg(target_env = "msvc")]
    c_config.flag("-utf-8");

    if std::env::var("TARGET").as_deref() == Ok("wasm32-unknown-unknown") {
        let Ok(wasm_headers) = std::env::var("DEP_TREE_SITTER_LANGUAGE_WASM_HEADERS") else {
            panic!(
                "Environment variable DEP_TREE_SITTER_LANGUAGE_WASM_HEADERS must be set by the \
                 language crate"
            );
        };
        let Ok(wasm_src) = std::env::var("DEP_TREE_SITTER_LANGUAGE_WASM_SRC").map(PathBuf::from)
        else {
            panic!(
                "Environment variable DEP_TREE_SITTER_LANGUAGE_WASM_SRC must be set by the \
                 language crate"
            );
        };

        c_config.include(&wasm_headers);
        c_config.files([
            wasm_src.join("stdio.c"),
            wasm_src.join("stdlib.c"),
            wasm_src.join("string.c"),
        ]);
    }

    let parser_path = src_dir.join("parser.c");
    assert!(
        parser_path.exists(),
        "{} has no src/parser.c; run `tree-sitter generate` in {}",
        library_name,
        manifest.display()
    );
    c_config.file(&parser_path);
    println!("cargo:rerun-if-changed={}", parser_path.display());

    // Only `just` and `vue` have one; the rest are pure generated parsers.
    let scanner_path = src_dir.join("scanner.c");
    if scanner_path.exists() {
        c_config.file(&scanner_path);
        println!("cargo:rerun-if-changed={}", scanner_path.display());
    }

    c_config.compile(&library_name);

    emit_query_cfgs(&manifest);
}

/// Declare and set the `with_*_query` cfgs upstream bindings guard their optional
/// query consts with.
///
/// GitComet deliberately does not vendor any grammar's `queries/` -- it keeps its
/// own in `crates/gitcomet-ui-gpui/src/view/rows/diff_text/queries/` -- so these
/// are always *off*. They are still declared, because `tree-sitter-vue`'s
/// `bindings/rust/lib.rs` is upstream verbatim and references all four; without
/// the `rustc-check-cfg` lines that file would warn about unexpected cfgs.
fn emit_query_cfgs(manifest: &Path) {
    for name in ["highlights", "injections", "locals", "tags"] {
        println!("cargo:rustc-check-cfg=cfg(with_{name}_query)");
        if manifest
            .join("queries")
            .join(format!("{name}.scm"))
            .exists()
        {
            println!("cargo:rustc-cfg=with_{name}_query");
        }
    }
}
